function hasEnglishPdfSidePanel(rawHtml) {
  const h = rawHtml || (typeof state !== 'undefined' ? (state.rawEnHtml || state.enHtml) : '') || '';
  return (
    /<div[^>]*class=["'][^"']*\b(?:col-xs-12\s+col-sm-4|col-sm-4|col-md-4|col-lg-4)\b[^"']*\bpull-right\b[^"']*["'][^>]*>/i.test(h) ||
    /class=["'][^"']*(?:col-xs-12\s+col-sm-4|col-md-4|col-sm-4|col-lg-4)[^"']*\bpull-right\b[^"']*["']/i.test(h) ||
    /<div[^>]*class=["'][^"']*\bpull-right\b[^"']*(?:col-xs-12\s+col-sm-4|col-md-4|col-sm-4|col-lg-4)[^"']*["']/i.test(h) ||
    /\b(?:col-xs-12\s+col-sm-4|col-md-4|col-sm-4|col-lg-4)\s+pull-right/i.test(h) ||
    /<div[^>]*class=["'][^"']*\bwell\b[^"']*["'][^>]*>(?:(?!<\/div>)[\s\S])*(?:Download in PDF format|\.pdf\b|Organization|Published)/i.test(h)
  );
}

function hasEnglishColXs12Sm4PullRight(rawHtml) {
  return hasEnglishPdfSidePanel(rawHtml);
}

function generateFrenchPdfSlug(frenchH1) {
  if (!frenchH1 || typeof frenchH1 !== 'string') return '';
  const clean = frenchH1.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  if (!clean) return '';

  const tokens = clean.split(/[\s_\-]+/);
  const kept = [];

  for (let token of tokens) {
    if (!token) continue;
    let coreWord = token;
    let hasElision = false;
    const elisionMatch = token.match(/^([a-zA-Z]['’])(.*)$/);
    if (elisionMatch) {
      const prefix = elisionMatch[1].toLowerCase().replace(/['’]/, '');
      if (['d', 'l', 's', 'c', 'qu', 'j', 'm', 't', 'n'].includes(prefix)) {
        hasElision = true;
        coreWord = elisionMatch[2];
      }
    }

    const norm = token.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, '');
    const normCore = coreWord.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, '');

    if (FRENCH_PDF_H1_CONJUNCTIONS.has(norm)) {
      continue;
    }

    if (hasElision && coreWord) {
      if (!FRENCH_PDF_H1_CONJUNCTIONS.has(normCore) && normCore.length > 0) {
        kept.push(normCore);
        continue;
      }
      continue;
    }

    if (!FRENCH_PDF_H1_CONJUNCTIONS.has(normCore) && normCore.length > 0) {
      kept.push(normCore);
    }
  }

  return kept.join('-');
}

function getFrenchDocumentH1() {
  const rawFr = state.rawFrDocxHtml || '';
  if (rawFr) {
    const parser = new DOMParser();
    const frDoc = parser.parseFromString(rawFr, 'text/html');
    const h1 = frDoc.querySelector('h1');
    if (h1 && h1.textContent.trim()) {
      return h1.textContent.trim();
    }
  }
  const frH1 = (state.frBlocks || []).find((b) => b.tag === 'h1');
  if (frH1 && frH1.text.trim()) {
    return frH1.text.trim();
  }
  return '';
}

function formatFrenchPdfOrganizationHtml(enOrgElOrText) {
  const text = typeof enOrgElOrText === 'string' ? enOrgElOrText : (enOrgElOrText ? (enOrgElOrText.textContent || '') : '');
  const html = typeof enOrgElOrText === 'string' ? enOrgElOrText : (enOrgElOrText ? (enOrgElOrText.innerHTML || '') : '');

  const hasHealthCanada = /Health\s+Canada/i.test(text) || /services\/health\.html/i.test(html) || /services\/sante\.html/i.test(html) || /Sant[ée]\s+Canada/i.test(text);
  const hasPhac = /Public\s+Health\s+Agency\s+of\s+Canada/i.test(text) || /public-health\.html/i.test(html) || /sante-publique\.html/i.test(html) || /Agence\s+de\s+la\s+sant[ée]\s+publique/i.test(text);
  const isAnd = /\band\b|\bet\b/i.test(text);

  const hcLink = '<a href="/content/canadasite/fr/services/sante.html">Santé Canada</a>';
  const phacLink = '<a href="/content/canadasite/fr/sante-publique.html">Agence de la santé publique du Canada</a>';

  let orgContent = '';
  if (hasHealthCanada && hasPhac) {
    const conj = isAnd ? ' et ' : ' ou ';
    orgContent = `${hcLink}${conj}${phacLink}`;
  } else if (hasHealthCanada) {
    orgContent = hcLink;
  } else if (hasPhac) {
    orgContent = phacLink;
  } else {
    let fallback = text.replace(/^Organization\s*[:：]\s*/i, '').replace(/^Organisation\s*[:：]\s*/i, '');
    GC_DEPARTMENT_MAPPINGS.forEach((dept) => {
      fallback = fallback.split(dept.enName).join(dept.frName);
    });
    fallback = fallback.replace(/href=["']([^"']+)["']/g, (m, href) => `href="${formatFrenchRootRelativeLink(href)}"`);
    orgContent = fallback.trim();
  }

  return `<strong>Organisation\u00A0:</strong> ${orgContent}`;
}

function formatFrenchPdfPublishedHtml(enPubElOrText) {
  let text = typeof enPubElOrText === 'string' ? enPubElOrText : (enPubElOrText ? (enPubElOrText.textContent || '') : '');
  text = text.replace(/\[TRANSLATION\s+MISSING\s*:\s*/gi, '').replace(/\]/g, '').trim();
  let dateVal = text.replace(/^(?:Date\s+published|Published|Date\s+de\s+publication|Publi[ée])\s*[:：]\s*/i, '').trim();
  if (!dateVal) {
    dateVal = '2026-03';
  }
  return `<strong>Date de publication\u00A0:</strong> ${dateVal}`;
}

function isPdfSidePanelContainer(el) {
  if (!el || !el.tagName) return false;
  const tag = el.tagName.toLowerCase();
  if (['body', 'html', 'main', 'article', 'section'].includes(tag)) return false;
  if (tag === 'p') return false;

  // Never treat top-level grid rows, page wrappers, or full-width containers as a PDF side panel
  if (el.classList && (
    el.classList.contains('col-xs-12') ||
    el.classList.contains('col-sm-12') ||
    el.classList.contains('col-md-12') ||
    el.classList.contains('col-lg-12') ||
    el.classList.contains('row') ||
    el.classList.contains('container')
  )) {
    return false;
  }

  // A side panel never contains main content headings
  if (el.querySelector && el.querySelector('h1, h2, h3, h4, h5, h6')) {
    return false;
  }

  // A true PDF side panel MUST contain publication download elements
  // (e.g. a figure with thumbnail/download link, or publication metadata: Organization, Published, Cat, ISBN)
  const hasFigureOrDownload = Boolean(
    el.querySelector && el.querySelector('figure') && (el.querySelector('figcaption') || el.querySelector('a[href*=".pdf"], img'))
  ) || Boolean(el.querySelector && el.querySelector('a[href*=".pdf"]'));
  
  const text = (el.textContent || '').toLowerCase();
  const hasPdfKeywords = /download\s+in\s+pdf|t[eé]l[eé]charger\s+en\s+format\s+pdf|\b\d+(?:[\.,]\d+)?\s*(?:mb|mo|kb|ko|pages)\b/i.test(text);
  const hasPubMetadata = /organization\s*:|published\s*:|cat(?:alogue)?\s*:|isbn\s*:/i.test(text) ||
                         /organisation\s*:|date\s+de\s+publication\s*:|catalogue\s*:|isbn\s*:/i.test(text);

  if (!hasFigureOrDownload && !(hasPdfKeywords && hasPubMetadata)) {
    return false;
  }

  const isCol = el.classList && (el.classList.contains('col-md-4') || el.classList.contains('col-sm-4') || el.classList.contains('col-lg-4'));
  const isPull = el.classList && el.classList.contains('pull-right');
  const hasWell = el.classList && el.classList.contains('well');
  const isAside = tag === 'aside';

  return isCol || isPull || hasWell || isAside;
}

function cleanFrenchDocImages(doc, rawEnHtml) {
  if (!doc || !doc.body) return;
  const enParser = new DOMParser();
  const enDocTemp = enParser.parseFromString(rawEnHtml || state.rawEnHtml || state.enHtml || '', 'text/html');
  const enImgs = Array.from(enDocTemp.querySelectorAll('img'));
  const frImgs = Array.from(doc.body.querySelectorAll('img'));

  frImgs.forEach((img, idx) => {
    const src = img.getAttribute('src') || '';
    let enImg = enImgs[idx];
    if (!enImg || (enImg.getAttribute('src') !== src && !src.includes(enImg.getAttribute('src') || '___'))) {
      const bySrc = enImgs.find((e) => e.getAttribute('src') === src || convertFrenchImageSrc(e.getAttribute('src') || '') === src);
      if (bySrc) enImg = bySrc;
    }
    const enAlt = enImg ? (enImg.getAttribute('alt') || '').trim() : '';
    const isEnEmptyAlt = !enAlt || isAutoGeneratedImageAlt(enAlt);
    if (isEnEmptyAlt && !isPdfSidePanelElement(img)) {
      img.setAttribute('alt', '');
      img.classList.remove('gc-swap-missing', 'gc-swap-editable');
      img.removeAttribute('title');
      img.removeAttribute('data-swap-index');
      img.removeAttribute('data-en-index');
      img.removeAttribute('data-fr-index');
    }
  });
}

function normalizePanelText(s) {
  return (s || '').replace(/\u00A0/g, ' ').replace(/\s+/g, ' ').trim().toLowerCase();
}

function panelHtmlText(html) {
  try {
    const tmp = document.createElement('div');
    tmp.innerHTML = html || '';
    return tmp.textContent || '';
  } catch (_) {
    return html || '';
  }
}

// Regenerate a panel field only when it still holds untranslated English or
// our own last-generated French (idempotent refresh, e.g. when the H1 slug
// backing download hrefs changes). Anything else is a user edit and must be
// preserved across rebuilds — otherwise typed panel text is wiped every time
// the preview or code output regenerates.
function shouldRegeneratePanelField(currentText, enText, generatedHtml) {
  const cur = normalizePanelText(currentText);
  if (!cur) return true;
  if (enText && cur === normalizePanelText(enText)) return true;
  if (generatedHtml && cur === normalizePanelText(panelHtmlText(generatedHtml))) return true;
  return false;
}

function autoLocalizeAllPdfSidePanels(docBody, rawEnHtml) {
  if (!docBody) return;
  const enParser = new DOMParser();
  const enDocTemp = enParser.parseFromString(rawEnHtml || state.rawEnHtml || state.enHtml || '', 'text/html');

  const panels = Array.from(docBody.querySelectorAll('.col-md-4, .col-sm-4, .col-lg-4, .pull-right, aside, .well')).filter(isPdfSidePanelContainer);
  const enPanel = enDocTemp ? Array.from(enDocTemp.querySelectorAll('.col-md-4, .col-sm-4, .col-lg-4, .pull-right, aside, .well')).find(isPdfSidePanelContainer) : null;

  panels.forEach((panel) => {
    // 1. Thumbnail img: alt must be empty per GC accessibility standards, but preserve navigation/highlight attributes
    panel.querySelectorAll('img').forEach((img) => {
      img.setAttribute('alt', '');
      img.classList.remove('gc-swap-missing');
      img.removeAttribute('title');
      const src = img.getAttribute('src');
      if (src) {
        img.setAttribute('src', convertFrenchImageSrc(src));
      }
    });

    // 2. Download link & size in figcaption
    const frenchH1 = getFrenchDocumentH1();

    let enDlHref = '';
    let enDlSize = '';
    if (enPanel) {
      const enA = enPanel.querySelector('a[href*=".pdf"], figcaption a');
      if (enA) enDlHref = enA.getAttribute('href') || '';
      const enP = enPanel.querySelector('figcaption p, figure p');
      if (enP) {
        const sizeM = enP.textContent.match(/\(([^)]+)\)/);
        if (sizeM) enDlSize = sizeM[1];
      }
    }
    if (!enDlSize) {
      const pText = panel.textContent || '';
      const sizeM = pText.match(/\(([^)]+)\)/);
      if (sizeM) enDlSize = sizeM[1];
    }

    const frDlA = panel.querySelector('a[href*=".pdf"], figcaption a');
    const localizedHref = localizePdfUrlWithFrenchH1((frDlA ? frDlA.getAttribute('href') : '') || enDlHref, frenchH1);
    const enFigP = enPanel ? enPanel.querySelector('figcaption p, figure p') : null;
    if (frDlA) {
      // Hrefs are functional: always refresh. Link text follows the
      // preserve-user-edits rule below.
      frDlA.setAttribute('href', localizedHref);
      const enDlA = enPanel ? enPanel.querySelector('a[href*=".pdf"], figcaption a') : null;
      if (shouldRegeneratePanelField(frDlA.textContent, enDlA ? enDlA.textContent : null, 'Télécharger en format PDF')) {
        frDlA.textContent = 'Télécharger en format PDF';
      }
    }

    const figP = panel.querySelector('figcaption p, figure p');
    const frSize = enDlSize ? convertPdfFileSizeAndPagesToFrench(enDlSize) : '1,31 Mo / Ko, 2 pages';
    const expectedFigText = `Télécharger en format PDF (${frSize})`;
    const regenFigcaption = !figP || shouldRegeneratePanelField(
      figP.textContent, enFigP ? enFigP.textContent : null, expectedFigText
    );
    if (figP && !regenFigcaption) {
      // User-edited caption: preserve the text, still refresh the href.
      const keepA = figP.querySelector('a[href*=".pdf"]');
      if (keepA) keepA.setAttribute('href', localizedHref);
      figP.classList.remove('gc-swap-missing');
      figP.removeAttribute('title');
    }
    if (figP && regenFigcaption) {
      const brLines = Array.from(figP.querySelectorAll('.gc-br-line'));
      if (brLines.length >= 2) {
        // Line 1: Download link
        brLines[0].innerHTML = `<a href="${localizedHref}">Télécharger en format PDF</a>`;
        brLines[0].classList.remove('gc-swap-missing');
        brLines[0].removeAttribute('title');
        // Line 2: Size & pages
        brLines[1].textContent = `(${frSize})`;
        brLines[1].classList.remove('gc-swap-missing');
        brLines[1].removeAttribute('title');
      } else if (brLines.length === 1) {
        brLines[0].innerHTML = `<a href="${localizedHref}">Télécharger en format PDF</a><br>\n          (${frSize})`;
        brLines[0].classList.remove('gc-swap-missing');
        brLines[0].removeAttribute('title');
        } else {
          const enBrLines = enFigP ? Array.from(enFigP.querySelectorAll('.gc-br-line')) : [];
        if (enBrLines.length >= 2) {
          const idx0 = enBrLines[0].getAttribute('data-swap-index') || enBrLines[0].getAttribute('data-en-index');
          const idx1 = enBrLines[1].getAttribute('data-swap-index') || enBrLines[1].getAttribute('data-en-index');
          const span0Attrs = idx0 !== null ? ` data-swap-index="${idx0}" data-en-index="${idx0}"` : '';
          const span1Attrs = idx1 !== null ? ` data-swap-index="${idx1}" data-en-index="${idx1}"` : '';
          figP.innerHTML = `<span class="gc-br-line gc-swap-editable" data-gc-line="0"${span0Attrs} contenteditable="true"><a href="${localizedHref}">Télécharger en format PDF</a></span><br>\n          <span class="gc-br-line gc-swap-editable" data-gc-line="1"${span1Attrs} contenteditable="true">(${frSize})</span>`;
        } else {
          const swapIdx = figP.getAttribute('data-swap-index');
          const enIdx = figP.getAttribute('data-en-index');
          const frIdx = figP.getAttribute('data-fr-index');
          figP.innerHTML = `<a href="${localizedHref}">Télécharger en format PDF</a><br>\n          (${frSize})`;
          if (swapIdx !== null) figP.setAttribute('data-swap-index', swapIdx);
          if (enIdx !== null) figP.setAttribute('data-en-index', enIdx);
          if (frIdx !== null) figP.setAttribute('data-fr-index', frIdx);
          figP.classList.add('gc-swap-editable');
        }
        figP.classList.remove('gc-swap-missing');
        figP.removeAttribute('title');
      }
    }

    // 3. Organization paragraph
    const orgP = Array.from(panel.querySelectorAll('p')).find((p) =>
      /Organization|Organisation/i.test(p.textContent) ||
      Boolean(p.querySelector('strong, b') && /Organization|Organisation/i.test(p.querySelector('strong, b').textContent))
    );
    if (orgP) {
      const enOrgP = enPanel ? Array.from(enPanel.querySelectorAll('p')).find((p) => /Organization|Organisation/i.test(p.textContent) || Boolean(p.querySelector('strong, b') && /Organization|Organisation/i.test(p.querySelector('strong, b').textContent))) : null;
      if (enPanel && !enOrgP) {
        orgP.remove();
      } else {
        const source = enOrgP ? (enOrgP.innerHTML || enOrgP.textContent) : (orgP.innerHTML || orgP.textContent);
        const generatedOrg = formatFrenchPdfOrganizationHtml(source);
        if (shouldRegeneratePanelField(orgP.textContent, enOrgP ? enOrgP.textContent : null, generatedOrg)) {
          orgP.innerHTML = generatedOrg;
        }
        orgP.classList.remove('gc-swap-missing');
        orgP.removeAttribute('title');
      }
    }

    // 4. Published date paragraph
    const pubP = Array.from(panel.querySelectorAll('p')).find((p) =>
      /Published|Date\s+de\s+publication|Publi[ée]/i.test(p.textContent) ||
      Boolean(p.querySelector('strong, b') && /Published|Date\s+de\s+publication|Publi[ée]/i.test(p.querySelector('strong, b').textContent))
    );
    if (pubP) {
      const enPubP = enPanel ? Array.from(enPanel.querySelectorAll('p')).find((p) => /Published|Date\s+de\s+publication|Publi[ée]/i.test(p.textContent) || Boolean(p.querySelector('strong, b') && /Published|Date\s+de\s+publication|Publi[ée]/i.test(p.querySelector('strong, b').textContent))) : null;
      const source = enPubP ? enPubP.textContent : pubP.textContent;
      const generatedPub = formatFrenchPdfPublishedHtml(source);
      if (shouldRegeneratePanelField(pubP.textContent, enPubP ? enPubP.textContent : null, generatedPub)) {
        pubP.innerHTML = generatedPub;
      }
      pubP.classList.remove('gc-swap-missing');
      pubP.removeAttribute('title');
    }

    // 5. Cat. # (if present)
    const catP = Array.from(panel.querySelectorAll('p')).find((p) =>
      /Cat\.|Catalogue/i.test(p.textContent)
    );
    if (catP) {
      const enCatP = enPanel ? Array.from(enPanel.querySelectorAll('p')).find((p) => /Cat\.|Catalogue/i.test(p.textContent)) : null;
      if (enPanel && !enCatP) {
        catP.remove();
      } else {
        const val = (enCatP ? enCatP.textContent : catP.textContent).replace(/^[^:：]+[:：]\s*/i, '').replace(/E-PDF/i, 'F-PDF').replace(/E\b/, 'F').trim();
        const generatedCat = `<strong>Cat.\u00A0:</strong> ${val}`;
        if (shouldRegeneratePanelField(catP.textContent, enCatP ? enCatP.textContent : null, generatedCat)) {
          catP.innerHTML = generatedCat;
        }
        catP.classList.remove('gc-swap-missing');
        catP.removeAttribute('title');
      }
    }

    // 6. ISBN (if present)
    const isbnP = Array.from(panel.querySelectorAll('p')).find((p) =>
      /ISBN/i.test(p.textContent)
    );
    if (isbnP) {
      const enIsbnP = enPanel ? Array.from(enPanel.querySelectorAll('p')).find((p) => /ISBN/i.test(p.textContent)) : null;
      if (enPanel && !enIsbnP) {
        isbnP.remove();
      } else {
        const val = (enIsbnP ? enIsbnP.textContent : isbnP.textContent).replace(/^ISBN\s*[:：]\s*/i, '').trim();
        const generatedIsbn = `<strong>ISBN\u00A0:</strong> ${val}`;
        if (shouldRegeneratePanelField(isbnP.textContent, enIsbnP ? enIsbnP.textContent : null, generatedIsbn)) {
          isbnP.innerHTML = generatedIsbn;
        }
        isbnP.classList.remove('gc-swap-missing');
        isbnP.removeAttribute('title');
      }
    }

    // 7. ISSN (if present)
    const issnP = Array.from(panel.querySelectorAll('p')).find((p) =>
      /ISSN/i.test(p.textContent)
    );
    if (issnP) {
      const enIssnP = enPanel ? Array.from(enPanel.querySelectorAll('p')).find((p) => /ISSN/i.test(p.textContent)) : null;
      const val = (enIssnP ? enIssnP.textContent : issnP.textContent).replace(/^ISSN\s*[:：]\s*/i, '').trim();
      const generatedIssn = `<strong>ISSN\u00A0:</strong> ${val}`;
      if (shouldRegeneratePanelField(issnP.textContent, enIssnP ? enIssnP.textContent : null, generatedIssn)) {
        issnP.innerHTML = generatedIssn;
      }
      issnP.classList.remove('gc-swap-missing');
      issnP.removeAttribute('title');
    }

    // 8. Updated (if present)
    const updP = Array.from(panel.querySelectorAll('p')).find((p) =>
      /Updated|Modified|Date\s+de\s+modification|Mis\s+à\s+jour/i.test(p.textContent)
    );
    if (updP) {
      const enUpdP = enPanel ? Array.from(enPanel.querySelectorAll('p')).find((p) => /Updated|Modified|Date\s+de\s+modification|Mis\s+à\s+jour/i.test(p.textContent)) : null;
      const val = (enUpdP ? enUpdP.textContent : updP.textContent).replace(/^[^:：]+[:：]\s*/i, '').trim();
      const generatedUpd = `<strong>Date de modification\u00A0:</strong> ${val}`;
      if (shouldRegeneratePanelField(updP.textContent, enUpdP ? enUpdP.textContent : null, generatedUpd)) {
        updP.innerHTML = generatedUpd;
      }
      updP.classList.remove('gc-swap-missing');
      updP.removeAttribute('title');
    }

    // 9. Clean any residual [TRANSLATION MISSING] wrappers within this panel
    panel.querySelectorAll('p, figure, figcaption, a, img').forEach((el) => {
      el.classList.remove('gc-swap-missing');
      el.removeAttribute('title');
      if (el.innerHTML && el.innerHTML.includes('[TRANSLATION MISSING')) {
        el.innerHTML = el.innerHTML
          .replace(/\[TRANSLATION\s+MISSING\s*:\s*/gi, '')
          .replace(/\]/g, '');
      }
    });
  });
}

function parsePdfSidePanelFromRoot(rootEl) {
  if (!rootEl) return null;
  let container = null;
  const candidates = Array.from(rootEl.querySelectorAll('.col-md-4, .col-sm-4, .pull-right, aside, .well'));
  for (const c of candidates) {
    if (isPdfSidePanelContainer(c)) {
      container = c.closest('.col-md-4, .col-sm-4, .pull-right, aside') || c;
      break;
    }
  }

  if (!container) return null;

  const well = container.querySelector('.well') || container;
  const imgEl = well.querySelector('figure img, img');
  const figcaption = well.querySelector('figcaption');
  const downloadLink = well.querySelector('a[href*=".pdf"]') || (figcaption ? figcaption.querySelector('a') : null);

  const fields = {
    container,
    hasPanel: true,
    thumbnail: null,
    download: null,
    organization: null,
    published: null,
    cat: null,
    isbn: null,
    issn: null,
    updated: null,
    author: null,
    otherParagraphs: [],
    fieldCount: 0,
  };

  if (imgEl) {
    fields.thumbnail = {
      src: imgEl.getAttribute('src') || '',
      alt: imgEl.getAttribute('alt') || '',
      className: imgEl.className || '',
    };
    fields.fieldCount++;
  }

  if (downloadLink || (figcaption && isPdfDownloadText(figcaption.textContent))) {
    const rawText = figcaption ? getBlockContent(figcaption) : downloadLink ? getBlockContent(downloadLink) : '';
    const sizeMatch = rawText.match(/\(([^)]+)\)/);
    fields.download = {
      href: downloadLink ? downloadLink.getAttribute('href') || '' : '',
      text: downloadLink ? downloadLink.textContent.trim() : 'Download in PDF format',
      sizeAndPages: sizeMatch ? sizeMatch[1].trim() : '',
      fullText: rawText,
    };
    fields.fieldCount++;
  }

  const paragraphs = Array.from(well.querySelectorAll('p')).filter((p) => !p.closest('figcaption'));
  paragraphs.forEach((p) => {
    const text = getBlockContent(p);
    const strong = p.querySelector('strong, b');
    const label = strong ? strong.textContent.trim() : '';

    if (/^Organization\s*[:：]/i.test(text) || /^Organisation\s*[:：]/i.test(text) || /^Organization\b/i.test(label) || /^Organisation\b/i.test(label)) {
      const links = Array.from(p.querySelectorAll('a')).map((a) => ({
        text: a.textContent.trim(),
        href: a.getAttribute('href') || '',
      }));
      fields.organization = { text, label, links, html: p.innerHTML };
      fields.fieldCount++;
    } else if (/^Published\s*[:：]/i.test(text) || /^Date\s+de\s+publication\s*[:：]/i.test(text) || /^Publié\s*[:：]/i.test(text) || /^Published\b/i.test(label)) {
      const val = text.replace(/^[^:：]+[:：]\s*/i, '').trim();
      fields.published = { text, label, date: val, html: p.innerHTML };
      fields.fieldCount++;
    } else if (/^Cat\.\s*[:：]/i.test(text) || /^N°\s*de\s*cat\.\s*[:：]/i.test(text) || /^Catalogue\s*[:：]/i.test(text) || /^Cat\b/i.test(label)) {
      const val = text.replace(/^[^:：]+[:：]\s*/i, '').trim();
      fields.cat = { text, label, number: val, html: p.innerHTML };
      fields.fieldCount++;
    } else if (/^ISBN\s*[:：]/i.test(text) || /^ISBN\b/i.test(label)) {
      const val = text.replace(/^[^:：]+[:：]\s*/i, '').trim();
      fields.isbn = { text, label, number: val, html: p.innerHTML };
      fields.fieldCount++;
    } else if (/^ISSN\s*[:：]/i.test(text) || /^ISSN\b/i.test(label)) {
      const val = text.replace(/^[^:：]+[:：]\s*/i, '').trim();
      fields.issn = { text, label, number: val, html: p.innerHTML };
      fields.fieldCount++;
    } else if (/^Updated\s*[:：]/i.test(text) || /^Date\s+de\s+modification\s*[:：]/i.test(text) || /^Mis\s+à\s+jour\s*[:：]/i.test(text) || /^Updated\b/i.test(label)) {
      const val = text.replace(/^[^:：]+[:：]\s*/i, '').trim();
      fields.updated = { text, label, date: val, html: p.innerHTML };
      fields.fieldCount++;
    } else if (/^Author\s*[:：]/i.test(text) || /^Auteur\s*[:：]/i.test(text) || /^Prepared\s+by\s*[:：]/i.test(text) || /^Préparé\s+par\s*[:：]/i.test(text) || /^Author\b/i.test(label)) {
      const val = text.replace(/^[^:：]+[:：]\s*/i, '').trim();
      fields.author = { text, label, author: val, html: p.innerHTML };
      fields.fieldCount++;
    } else if (text.trim()) {
      fields.otherParagraphs.push({ text, html: p.innerHTML });
      fields.fieldCount++;
    }
  });

  return fields;
}

function convertPdfFileSizeAndPagesToFrench(str) {
  if (!str) return str;
  return str
    .replace(/(\d+)\.(\d+)\s*(MB|Mo)/gi, '$1,$2\u00A0Mo')
    .replace(/(\d+)\s*(MB|Mo)/gi, '$1\u00A0Mo')
    .replace(/(\d+)\.(\d+)\s*(KB|Ko)/gi, '$1,$2\u00A0Ko')
    .replace(/(\d+)\s*(KB|Ko)/gi, '$1\u00A0Ko')
    .replace(/(\d+)\.(\d+)\s*(GB|Go)/gi, '$1,$2\u00A0Go')
    .replace(/(\d+)\s*(GB|Go)/gi, '$1\u00A0Go')
    .replace(/\bMB\b/g, 'Mo')
    .replace(/\bKB\b/g, 'Ko')
    .replace(/\bGB\b/g, 'Go')
    .replace(/\bpages?\b/gi, 'pages')
    .replace(/\s+/g, ' ')
    .trim();
}

function synthesizeFrenchPdfSidePanelBlock(enBlock) {
  if (!enBlock) return '';
  const text = enBlock.text || '';

  // 1. Download link & size
  if (isPdfDownloadText(text) || (enBlock.el && enBlock.el.closest && enBlock.el.closest('figcaption'))) {
    const sizeMatch = text.match(/\(([^)]+)\)/);
    const frenchSize = sizeMatch ? `\n(${convertPdfFileSizeAndPagesToFrench(sizeMatch[1])})` : '';
    return `Télécharger en format PDF${frenchSize}`;
  }

  // 2. Organization
  if (/^Organization\s*[:：]/i.test(text)) {
    if (hasEnglishColXs12Sm4PullRight()) {
      const orgHtml = formatFrenchPdfOrganizationHtml(enBlock.el || text);
      return orgHtml.replace(/<[^>]+>/g, '').replace(/&nbsp;/g, '\u00A0');
    }
    const cleanText = text.replace(/^Organization\s*[:：]\s*/i, '');
    let frenchBody = cleanText;
    GC_DEPARTMENT_MAPPINGS.forEach((dept) => {
      frenchBody = frenchBody.split(dept.enName).join(dept.frName);
    });
    frenchBody = frenchBody.replace(/\bor\b/g, 'ou').replace(/\band\b/g, 'et');
    return `Organisation\u00A0: ${frenchBody}`;
  }

  // 3. Published
  if (/^Published\s*[:：]/i.test(text)) {
    const val = text.replace(/^Published\s*[:：]\s*/i, '');
    return `Date de publication\u00A0: ${val}`;
  }

  // 4. Cat. #
  if (/^Cat\.\s*[:：]/i.test(text) || /^Catalogue\s*[:：]/i.test(text)) {
    const val = text.replace(/^[^:：]+[:：]\s*/i, '').replace(/E-PDF/i, 'F-PDF').replace(/E\b/, 'F');
    return `Cat.\u00A0: ${val}`;
  }

  // 5. ISBN
  if (/^ISBN\s*[:：]/i.test(text)) {
    const val = text.replace(/^ISBN\s*[:：]\s*/i, '');
    return `ISBN\u00A0: ${val}`;
  }

  // 6. ISSN
  if (/^ISSN\s*[:：]/i.test(text)) {
    const val = text.replace(/^ISSN\s*[:：]\s*/i, '');
    return `ISSN\u00A0: ${val}`;
  }

  // 7. Updated
  if (/^Updated\s*[:：]/i.test(text) || /^Modified\s*[:：]/i.test(text)) {
    const val = text.replace(/^[^:：]+[:：]\s*/i, '');
    return `Date de modification\u00A0: ${val}`;
  }

  // 8. Author / Prepared by
  if (/^Author\s*[:：]/i.test(text)) {
    const val = text.replace(/^Author\s*[:：]\s*/i, '');
    return `Auteur\u00A0: ${val}`;
  }
  if (/^Prepared\s+by\s*[:：]/i.test(text)) {
    const val = text.replace(/^Prepared\s+by\s*[:：]\s*/i, '');
    return `Préparé par\u00A0: ${val}`;
  }

  return applyFrenchTypographyRules(text);
}

function getSampleOrBoilerplateTranslation(text) {
  if (!text) return null;
  const clean = text.trim();
  if (/Health Canada evaluates the safety, efficacy, and quality of therapeutic health products and prescription pharmaceuticals available to patients and healthcare professionals throughout Canada/i.test(clean)) {
    return "Santé Canada évalue l'innocuité, l'efficacité et la qualité des produits de santé thérapeutiques et des produits pharmaceutiques sur ordonnance offerts aux patients et aux professionnels de la santé partout au Canada.";
  }
  return null;
}

function computePdfSidePanelAudit() {
  const parser = new DOMParser();
  const enDoc = parser.parseFromString(state.rawEnHtml || '', 'text/html');
  const frDoc = parser.parseFromString(state.rawFrDocxHtml || state.frenchHtmlOutput || '', 'text/html');

  const enPanel = parsePdfSidePanelFromRoot(enDoc.body);
  const frPanel = parsePdfSidePanelFromRoot(frDoc.body);

  const items = [];

  if (!enPanel && !frPanel) {
    return {
      hasEnPanel: false,
      hasFrPanel: false,
      activeCount: 0,
      rows: [],
      message: 'No PDF side panel detected in English source HTML.',
      status: 'none',
    };
  }

  // 1. Thumbnail Image Preview
  if (enPanel && enPanel.thumbnail) {
    items.push({
      field: 'thumbnail',
      label: 'Publication Cover Thumbnail',
      enValue: `<img src="${escapeHtml(enPanel.thumbnail.src)}" alt="${escapeHtml(enPanel.thumbnail.alt)}" class="h-10 rounded border border-border inline-block mr-2"><code class="text-[11px]">${escapeHtml(enPanel.thumbnail.src)}</code>`,
      frValue: frPanel && frPanel.thumbnail
        ? `<img src="${escapeHtml(frPanel.thumbnail.src)}" alt="${escapeHtml(frPanel.thumbnail.alt)}" class="h-10 rounded border border-border inline-block mr-2"><code class="text-[11px]">${escapeHtml(frPanel.thumbnail.src)}</code>`
        : `<span class="text-xs text-emerald-600 dark:text-emerald-400 font-medium">✓ Auto-localized with French image rules</span>`,
      status: frPanel && frPanel.thumbnail ? 'matched' : 'synthesized',
      statusLabel: frPanel && frPanel.thumbnail ? 'Matched in Docx' : 'Auto-Preserved in French DOM',
    });
  }

  // 2. Download Link & Size
  if (enPanel && enPanel.download) {
    const isColXs12 = hasEnglishColXs12Sm4PullRight();
    const enHref = enPanel.download.href;
    const frenchH1 = getFrenchDocumentH1();
    const frHref = frPanel && frPanel.download ? frPanel.download.href : localizePdfUrlWithFrenchH1(enHref, frenchH1);
    const enSize = enPanel.download.sizeAndPages;
    const frSize = frPanel && frPanel.download ? frPanel.download.sizeAndPages : convertPdfFileSizeAndPagesToFrench(enSize);

    const defaultFrDlText = 'Télécharger en format PDF';
    const frDlText = frPanel && frPanel.download ? frPanel.download.text : defaultFrDlText;

    items.push({
      field: 'download',
      label: 'Download Link & Size',
      enValue: `<div><strong>${escapeHtml(enPanel.download.text)}</strong> ${enSize ? `<span class="text-text-secondary">(${escapeHtml(enSize)})</span>` : ''}</div><div class="text-[11px] font-mono text-text-muted truncate mt-0.5">${escapeHtml(enHref)}</div>`,
      frValue: `<div><strong>${escapeHtml(frDlText)}</strong> ${frSize ? `<span class="text-text-secondary">(${escapeHtml(frSize)})</span>` : ''}</div><div class="text-[11px] font-mono text-emerald-600 dark:text-emerald-400 truncate mt-0.5">${escapeHtml(frHref)}</div>`,
      status: frPanel && frPanel.download ? 'matched' : 'synthesized',
      statusLabel: frPanel && frPanel.download ? 'Matched in Docx' : isColXs12 ? 'French H1 Slug URL (-fra.pdf)' : 'Auto-Localized GC Standard (-fra.pdf)',
    });
  }

  // 3. Organization & Departments
  if (enPanel && enPanel.organization) {
    const isColXs12 = hasEnglishColXs12Sm4PullRight();
    const enOrgText = enPanel.organization.text;
    const frOrgHtml = isColXs12
      ? formatFrenchPdfOrganizationHtml(enPanel.organization.html || enOrgText)
      : frPanel && frPanel.organization
      ? escapeHtml(frPanel.organization.text)
      : synthesizeFrenchPdfSidePanelBlock({ text: enOrgText, el: document.createElement('p') });

    items.push({
      field: 'organization',
      label: 'Organization & Departments',
      enValue: escapeHtml(enOrgText),
      frValue: frOrgHtml,
      status: frPanel && frPanel.organization ? 'matched' : 'synthesized',
      statusLabel: frPanel && frPanel.organization ? 'Matched in Docx' : isColXs12 ? 'Health Canada / PHAC Proper Links' : 'Auto-Mapped GC Departments',
    });
  } else {
    items.push({
      field: 'organization',
      label: 'Organization & Departments',
      enValue: '<span class="text-text-muted italic">Not in English panel</span>',
      frValue: '<span class="text-text-muted italic">Omitted (Not needed)</span>',
      status: 'omitted',
      statusLabel: '○ Omitted (Not in English)',
    });
  }

  // 4. Published Date
  if (enPanel && enPanel.published) {
    const enPubText = enPanel.published.text;
    const frPubText = frPanel && frPanel.published
      ? frPanel.published.text
      : synthesizeFrenchPdfSidePanelBlock({ text: enPubText, el: document.createElement('p') });

    items.push({
      field: 'published',
      label: 'Date Published',
      enValue: escapeHtml(enPubText),
      frValue: escapeHtml(frPubText),
      status: frPanel && frPanel.published ? 'matched' : 'synthesized',
      statusLabel: frPanel && frPanel.published ? 'Matched in Docx' : 'Auto-Formatted Date',
    });
  } else {
    items.push({
      field: 'published',
      label: 'Date Published',
      enValue: '<span class="text-text-muted italic">Not in English panel</span>',
      frValue: '<span class="text-text-muted italic">Omitted (Not needed)</span>',
      status: 'omitted',
      statusLabel: '○ Omitted (Not in English)',
    });
  }

  // 5. Cat. #
  if (enPanel && enPanel.cat) {
    const enCatText = enPanel.cat.text;
    const frCatText = frPanel && frPanel.cat
      ? frPanel.cat.text
      : synthesizeFrenchPdfSidePanelBlock({ text: enCatText, el: document.createElement('p') });

    items.push({
      field: 'cat',
      label: 'Catalogue Number (Cat. #)',
      enValue: escapeHtml(enCatText),
      frValue: escapeHtml(frCatText),
      status: frPanel && frPanel.cat ? 'matched' : 'synthesized',
      statusLabel: frPanel && frPanel.cat ? 'Matched in Docx' : 'Auto-Converted (F-PDF)',
    });
  } else {
    items.push({
      field: 'cat',
      label: 'Catalogue Number (Cat. #)',
      enValue: '<span class="text-text-muted italic">Not in English panel</span>',
      frValue: '<span class="text-text-muted italic">Omitted (Not needed)</span>',
      status: 'omitted',
      statusLabel: '○ Omitted (Not in English)',
    });
  }

  // 6. ISBN
  if (enPanel && enPanel.isbn) {
    const enIsbnText = enPanel.isbn.text;
    const frIsbnText = frPanel && frPanel.isbn
      ? frPanel.isbn.text
      : synthesizeFrenchPdfSidePanelBlock({ text: enIsbnText, el: document.createElement('p') });

    items.push({
      field: 'isbn',
      label: 'ISBN Number',
      enValue: escapeHtml(enIsbnText),
      frValue: escapeHtml(frIsbnText),
      status: frPanel && frPanel.isbn ? 'matched' : 'synthesized',
      statusLabel: frPanel && frPanel.isbn ? 'Matched in Docx' : 'Auto-Synchronized',
    });
  } else {
    items.push({
      field: 'isbn',
      label: 'ISBN Number',
      enValue: '<span class="text-text-muted italic">Not in English panel</span>',
      frValue: '<span class="text-text-muted italic">Omitted (Not needed)</span>',
      status: 'omitted',
      statusLabel: '○ Omitted (Not in English)',
    });
  }

  // 7. ISSN (if present in English)
  if (enPanel && enPanel.issn) {
    const enIssnText = enPanel.issn.text;
    const frIssnText = frPanel && frPanel.issn
      ? frPanel.issn.text
      : synthesizeFrenchPdfSidePanelBlock({ text: enIssnText, el: document.createElement('p') });

    items.push({
      field: 'issn',
      label: 'ISSN Number',
      enValue: escapeHtml(enIssnText),
      frValue: escapeHtml(frIssnText),
      status: frPanel && frPanel.issn ? 'matched' : 'synthesized',
      statusLabel: frPanel && frPanel.issn ? 'Matched in Docx' : 'Auto-Synchronized',
    });
  }

  // 8. Updated / Modified (if present in English)
  if (enPanel && enPanel.updated) {
    const enUpdText = enPanel.updated.text;
    const frUpdText = frPanel && frPanel.updated
      ? frPanel.updated.text
      : synthesizeFrenchPdfSidePanelBlock({ text: enUpdText, el: document.createElement('p') });

    items.push({
      field: 'updated',
      label: 'Date Modified / Updated',
      enValue: escapeHtml(enUpdText),
      frValue: escapeHtml(frUpdText),
      status: frPanel && frPanel.updated ? 'matched' : 'synthesized',
      statusLabel: frPanel && frPanel.updated ? 'Matched in Docx' : 'Auto-Formatted Date',
    });
  }

  // 9. Author / Prepared by (if present in English)
  if (enPanel && enPanel.author) {
    const enAuthText = enPanel.author.text;
    const frAuthText = frPanel && frPanel.author
      ? frPanel.author.text
      : synthesizeFrenchPdfSidePanelBlock({ text: enAuthText, el: document.createElement('p') });

    items.push({
      field: 'author',
      label: 'Author / Prepared by',
      enValue: escapeHtml(enAuthText),
      frValue: escapeHtml(frAuthText),
      status: frPanel && frPanel.author ? 'matched' : 'synthesized',
      statusLabel: frPanel && frPanel.author ? 'Matched in Docx' : 'Auto-Translated',
    });
  }

  const activeCount = items.filter((it) => it.status !== 'omitted').length;

  return {
    hasEnPanel: Boolean(enPanel),
    hasFrPanel: Boolean(frPanel),
    enPanel,
    frPanel,
    activeCount,
    rows: items,
    status: 'ok',
  };
}

function autoLocalizePdfSidePanel() {
  const parser = new DOMParser();
  const doc = parser.parseFromString(state.rawEnHtml || '', 'text/html');
  const enPanel = parsePdfSidePanelFromRoot(doc.body);
  if (!enPanel) {
    showToast('No PDF side panel found in English HTML to localize.');
    return;
  }

  // Ensure all .pdf links are converted to -fra.pdf
  doc.body.querySelectorAll('.col-md-4 a[href*=".pdf"], .well a[href*=".pdf"]').forEach((a) => {
    const raw = a.getAttribute('href');
    if (raw) a.setAttribute('href', localizePdfUrl(raw));
  });

  computeAlignment();
}

function insertStandardPdfSidePanel() {
  const sampleSnippet = `
<div class="col-xs-12 col-sm-4 pull-right">
  <div class="well">
    <figure> <img src="/content/dam/hc-sc/images/publications/drugs-health-products/pdf-320x414.gif" alt="" class="img-responsive hidden-sm hidden-xs mrgn-bttm-lg">
      <figcaption>
        <p><a href="/content/dam/hc-sc/documents/services/drugs-health-products/publication-eng.pdf">Download in PDF format</a><br>
          (2.4 MB, 48 pages)</p>
      </figcaption>
    </figure>
    <p><strong>Published:</strong> 2026-03</p>
  </div>
</div>`;

  const parser = new DOMParser();
  const doc = parser.parseFromString(state.rawEnHtml || '<p></p>', 'text/html');
  const h1 = doc.body.querySelector('h1');
  if (h1) {
    h1.insertAdjacentHTML('afterend', sampleSnippet);
  } else if (doc.body.firstChild) {
    doc.body.insertAdjacentHTML('afterbegin', sampleSnippet);
  } else {
    doc.body.innerHTML = sampleSnippet;
  }

  state.rawEnHtml = doc.body.innerHTML;
  computeAlignment();
}

